//! Required OL type DOMString reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><ol id=list type=MiXeD>Fallback ordered list</ol><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://ol-type.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn ol_type_canonical_accessor_descriptor_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),P=HTMLOListElement.prototype,a=Object.getOwnPropertyDescriptor(P,'type');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get type'||a.set.name!=='set type'||Object.hasOwn(x,'type')||x.type!=='MiXeD'||x.textContent!=='Fallback ordered list')throw 'canonical ordered list type accessor';"#);}
#[test]
fn ol_type_native_domstring_aliases_old_values_and_absent_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),attr=x.getAttributeNode('type'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.type='A\ud800Z';var records=watch.takeRecords();if(x.type!=='A\ud800Z'||attr.value!==x.type||x.getAttributeNode('type')!==attr||records.length!==1||records[0].attributeName!=='type'||records[0].oldValue!=='MiXeD'||x.textContent!=='Fallback ordered list')throw 'exact ordered list type transaction';attr.nodeValue='unrestricted';if(x.type!=='unrestricted')throw 'ordinary string reflection';x.removeAttribute('type');if(x.type!==''||attr.ownerElement!==null||attr.value!=='unrestricted')throw 'removed type default';x.type=null;if(x.type!=='null'||document.getElementById('neighbor').value!=='seed')throw 'null DOMString conversion';"#);}
#[test]
fn ol_type_inert_exact_namespace_once_conversion_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:ol');if(!(x instanceof HTMLOListElement)||x.type!=='')throw 'inert ordered list type default';var calls=0;x.type={toString:function(){calls++;x.setAttribute('type','author');return 'R\udfffZ';}};if(calls!==1||x.type!=='R\udfffZ'||x.getAttribute('type')!==x.type)throw 'once exact conversion';x.setAttributeNS('urn:foreign','type','foreign');x.setAttributeNS(null,'TYPE','upper');if(x.type!=='R\udfffZ')throw 'exact null namespace type';var clone=x.cloneNode(false);if(clone.type!==x.type)throw 'namespace copy';x.removeAttributeNS('urn:foreign','type');x.removeAttributeNS(null,'TYPE');var copy=document.importNode(x,false);if(copy.type!==x.type||copy.ownerDocument!==document||clone.getAttributeNode('type')===x.getAttributeNode('type'))throw 'actual copies';clone.type='independent';if(x.type!=='R\udfffZ'||copy.type!=='R\udfffZ')throw 'independent copied type';"#);}
#[test]
fn ol_type_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),old=x.getAttributeNode('type'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.type={toString:function(){calls++;x.removeAttribute('type');x.setAttribute('type','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('type'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='MiXeD'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.type={toString:function(){x.setAttribute('type','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.type!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.type=Symbol('div');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.type!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.type=value;if(x.type!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='Fallback ordered list')throw 'metadata leaves displayed text';"#);
}

#[test]
fn ol_type_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),C=HTMLOListElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'type'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('h1'),document.createElement('div'),document.createElement('legend'),document.createElement('ul'),document.createElement('li'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','ol'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OL')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'type',{value:'author',writable:true,configurable:true});if(x.type!=='author'||a.get.call(x)!=='MiXeD')throw 'canonical authority';a.set.call(x,'canonical');if(x.type!=='author'||x.getAttribute('type')!=='canonical')throw 'borrowed real setter';delete x.type;if(x.type!=='canonical'||Object.hasOwn(x,'type'))throw 'restored inherited reflection';delete window.HTMLOListElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}

#[test]
fn ol_type_native_inert_attribute_aliases_namespace_and_exact_copies(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','ol');x.setAttribute('type','MiXeD');"}else{"var x=document.getElementById('list');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('type');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.type!=='R\ud800'+writer||x.getAttributeNode('type')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','type','foreign');x.setAttributeNS(null,'TYPE','upper');if(x.type!=='R\ud800textContent'||x.getAttributeNodeNS(null,'type')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'type','no date parsing');if(x.type!=='no date parsing'||a.value!==x.type)throw 'exact null namespace writer';var copy=x.cloneNode(false);if(copy.type!==x.type||copy.getAttributeNode('type')===a)throw 'independent clone';x.removeAttributeNS(null,'type');if(x.type!==''||a.ownerElement!==null||copy.type!=='no date parsing')throw 'removed actual default';"#);}
}

#[test]
fn ol_type_native_adoption_and_return_keep_actual_interface_attr_and_child_handles(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),attr=x.getAttributeNode('type'),first=x.firstChild,list=x.childNodes,C=HTMLOListElement,doc=new Document();if(doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.parentNode!==null||!(x instanceof C)||x.type!=='MiXeD'||attr.ownerElement!==x||attr.ownerDocument!==doc||x.firstChild!==first||x.childNodes!==list)throw 'actual native data adoption';x.type='A\udfffZ';if(document.adoptNode(x)!==x||x.ownerDocument!==document||x.type!=='A\udfffZ'||x.getAttributeNode('type')!==attr)throw 'same native identity return';document.body.appendChild(x);if(x.firstChild!==first||x.childNodes!==list||x.textContent!=='Fallback ordered list'||attr.value!==x.type)throw 'reconnected data source';"#);
}

#[test]
fn ol_type_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLOListElement,a=Object.getOwnPropertyDescriptor(C.prototype,'type'),calls=0;if(C===HTMLOListElement||a.get.call(x)!=='MiXeD')throw 'captured data accessor';"#);p.set_location(&crate::navigation::address("https://other-ol-type.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://ol-type.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'data origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.

#[test]
fn ol_type_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.type='Long canonical \ud800 OL typement replacement';",r"x.setAttribute('type','Long canonical \ud800 OL typement replacement');",r"attr.value='Long canonical \ud800 OL typement replacement';",r"attr.nodeValue='Long canonical \ud800 OL typement replacement';",r"attr.textContent='Long canonical \ud800 OL typement replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','ol');x.setAttribute('type','MiXeD');"}else{"var x=document.getElementById('list');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('type'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("value writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='MiXeD'||x.type!=='MiXeD'||watch.takeRecords().length)throw 'atomic value writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.type!=='Long canonical \ud800 OL typement replacement'||records.length!==1||records[0].oldValue!=='MiXeD'||records[0].attributeName!=='type'||x.getAttributeNode('type')!==attr)throw 'fresh value writer recovery';");
 }}}
}

#[test]
fn ol_type_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var data=new Document().createElementNS('http://www.w3.org/1999/xhtml','ol');data.type='A\ud800Z';");let Value::Host(object)=p.runtime.execute("data;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert data handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('list').type='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("list")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.ol_type_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.ol_type_get(object).is_ok());}}
}

#[test]
fn ol_type_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["ol"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById('list');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.type='exact';source.appendChild(doc.createTextNode('Fallback'));");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.type='exact';source.appendChild(doc.createTextNode('Fallback'));");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('type');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('type')!==oldValue||watch.takeRecords().length)throw 'atomic ordered-list lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('type')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.type!==source.type||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}

#[test]
fn ol_type_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["ol"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.type='exact';source.appendChild(owner.createTextNode('Reserved'));var first=source.firstChild,attr=source.getAttributeNode('type');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('type')!==attr||source.type!=='exact'||source.parentNode!==target)throw 'reserved native ordered-list connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}

#[test]
fn ol_type_native_deep_clone_import_template_and_fallback_keep_actual_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list');x.type='A\ud800Z';var first=x.firstChild,copy=x.cloneNode(true),a=copy.getAttributeNode('type'),list=copy.childNodes;copy.id='copy';document.body.appendChild(copy);if(!(copy instanceof HTMLOListElement)||copy.type!==x.type||copy.firstChild===first||copy.textContent!=='Fallback ordered list'||a===x.getAttributeNode('type'))throw 'actual deep data clone';copy.textContent='Changed\udfff';if(copy.type!==x.type||copy.childNodes!==list||list.length!==1||copy.textContent!=='Changed\udfff'||x.firstChild!==first)throw 'actual data fallback replacement';var doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','ol');source.type='I\ud800Z';source.appendChild(doc.createTextNode('Inert fallback'));var imported=document.importNode(source,true);document.body.appendChild(imported);if(imported.type!==source.type||imported.firstChild===source.firstChild||imported.textContent!=='Inert fallback'||source.ownerDocument!==doc)throw 'actual deep data import';var leaf=imported.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(leaf.type!==imported.type||leaf.parentNode!==template.content||leaf.ownerDocument!==template.content.ownerDocument)throw 'actual data template parking';"#);
}

#[test]
fn ol_type_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="ol"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','ol'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.type!=='MiXeD')throw 'active content copy guard';");}
}

